-- Check: 140 responses, scored count, held scores, actions; then the cycle results.
select count(*) as responses, count(score) as scored, count(*) filter (where gap_remarks like '[Workbook score%') as held_below_workbook
  from public.responses where cycle_id = '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid;
select count(*) as actions from public.actions where cycle_id = '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid;
select grp, label, scored, maturity_index, maturity_band, mandatory_compliance, high_gaps
  from public.v_cycle_results where cycle_id = '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid order by grp;
